from dataclasses import dataclass

@dataclass(frozen=True)
class Token:
    kind: str
    text: str

class LexError(ValueError):
    pass

def tokenize(source: str) -> list[Token]:
    result, index = [], 0
    punctuation = ".[]|,():{}$\"+"
    while index < len(source):
        if source[index].isspace():
            index += 1
            continue
        if source[index] in punctuation:
            if source[index] == '"':
                end, escaped = index + 1, False
                while end < len(source):
                    if source[end] == '"' and not escaped:
                        break
                    escaped = source[end] == "\\" and not escaped
                    if source[end] != "\\":
                        escaped = False
                    end += 1
                if end >= len(source):
                    raise LexError("unterminated string")
                result.append(Token("STRING", source[index:end + 1]))
                index = end + 1
            else:
                result.append(Token(source[index], source[index]))
                index += 1
            continue
        end = index
        while end < len(source) and not source[end].isspace() and source[end] not in punctuation:
            end += 1
        text = source[index:end]
        kind = "LITERAL" if text in {"true", "false", "null"} or text.replace(".", "", 1).replace("-", "", 1).isdigit() else "WORD"
        result.append(Token(kind, text))
        index = end
    result.append(Token("EOF", ""))
    return result

import json
from dataclasses import dataclass
from typing import Any
from jq_lexer import Token, tokenize

class ParseError(ValueError):
    pass
@dataclass(frozen=True)
class Identity: pass
@dataclass(frozen=True)
class Literal: value: Any
@dataclass(frozen=True)
class Field: name: str
@dataclass(frozen=True)
class Iterate: pass
@dataclass(frozen=True)
class Pipe: left: Any; right: Any
@dataclass(frozen=True)
class Comma: left: Any; right: Any
@dataclass(frozen=True)
class Array: expression: Any
@dataclass(frozen=True)
class Add: left: Any; right: Any

class Parser:
    def __init__(self, tokens: list[Token]): self.tokens, self.position = tokens, 0
    def current(self) -> Token: return self.tokens[self.position]
    def take(self, kind: str) -> Token:
        token = self.current()
        if token.kind != kind: raise ParseError(f"expected {kind}")
        self.position += 1
        return token
    def parse(self) -> Any:
        value = self.comma(); self.take("EOF"); return value
    def comma(self) -> Any:
        value = self.pipe()
        while self.current().kind == ",":
            self.position += 1; value = Comma(value, self.pipe())
        return value
    def pipe(self) -> Any:
        value = self.add()
        while self.current().kind == "|":
            self.position += 1; value = Pipe(value, self.add())
        return value

    def add(self) -> Any:
        value = self.primary()
        while self.current().kind == "+":
            self.position += 1
            value = Add(value, self.primary())
        return value
    def primary(self) -> Any:
        token = self.current()
        if token.kind == ".":
            self.position += 1
            value = Field(self.current().text) if self.current().kind == "WORD" else Identity()
            if isinstance(value, Field): self.position += 1
        elif token.kind == "LITERAL":
            self.position += 1; value = Literal(json.loads(token.text))
        elif token.kind == "STRING":
            self.position += 1; value = Literal(json.loads(token.text))
        elif token.kind == "[":
            self.position += 1; value = Array(self.comma()); self.take("]")
        else: raise ParseError("unexpected token")
        if self.current().kind == "[":
            self.position += 1; self.take("]"); value = Iterate()
        return value

def parse(source: str) -> Any: return Parser(tokenize(source)).parse()

import sys
from jq_evaluator import RuntimeErrorJq, evaluate
from jq_parser import ParseError, parse
from jq_values import encode_compact, parse_json

def main(argv: list[str]) -> int:
    if len(argv) != 2 or argv[0] != "-c" or not argv[1]:
        print("usage: jq -c PROGRAM", file=sys.stderr); return 3
    try: program = parse(argv[1])
    except (ParseError, ValueError) as error:
        print(str(error), file=sys.stderr); return 3
    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            input_value = parse_json(line)
            for value in evaluate(program, input_value):
                sys.stdout.write(encode_compact(value) + "\n")
    except (RuntimeErrorJq, ValueError) as error:
        print(str(error), file=sys.stderr); return 5
    return 0
from collections.abc import Iterator
from typing import Any
from jq_parser import Add, Array, Comma, Field, Identity, Iterate, Literal, Pipe

class RuntimeErrorJq(Exception): pass

def evaluate(expression: Any, value: Any) -> Iterator[Any]:
    if isinstance(expression, Identity): yield value
    elif isinstance(expression, Literal): yield expression.value
    elif isinstance(expression, Field):
        if not isinstance(value, dict): raise RuntimeErrorJq("cannot index value")
        yield value.get(expression.name)
    elif isinstance(expression, Iterate):
        if isinstance(value, (list, dict)): yield from value if isinstance(value, list) else value.values()
        elif value is not None: raise RuntimeErrorJq("cannot iterate value")
    elif isinstance(expression, Pipe):
        for item in evaluate(expression.left, value): yield from evaluate(expression.right, item)
    elif isinstance(expression, Add):
        left_values = list(evaluate(expression.left, value))
        right_values = list(evaluate(expression.right, value))
        for left in left_values:
            for right in right_values:
                if isinstance(left, bool) or isinstance(right, bool):
                    raise RuntimeErrorJq("cannot add values")
                try:
                    yield left + right
                except (TypeError, ValueError) as error:
                    raise RuntimeErrorJq("cannot add values") from error
    elif isinstance(expression, Comma):
        yield from evaluate(expression.left, value); yield from evaluate(expression.right, value)
    elif isinstance(expression, Array): yield list(evaluate(expression.expression, value))
    else: raise RuntimeErrorJq("unknown expression")
import json, subprocess, sys
from pathlib import Path
ROOT = Path(__file__).parent.parent
def run(program, value):
    return subprocess.run([sys.executable, str(ROOT / "jq"), "-c", program], input=json.dumps(value)+"\n", capture_output=True, text=True)
def test_identity_runtime():
    result = run(".", None); assert result.returncode == 0; assert [json.loads(x) for x in result.stdout.splitlines()] == [None]
def test_array_iteration_preserves_generator_order():
    result = run("[.[]]", [1,2,3]); assert result.returncode == 0; assert [json.loads(x) for x in result.stdout.splitlines()] == [[1,2,3]]
def test_compile_error_exit_code(): assert run("[", {}).returncode == 3

def test_cli_adds_one_and_emits_compact_json():
    result = run(". + 1", 41)
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == [42]

def test_cli_processes_newline_delimited_inputs_in_order():
    result = subprocess.run(
        [sys.executable, str(ROOT / "jq"), "-c", "."],
        input="1\n2\n3\n", capture_output=True, text=True,
    )
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == [1, 2, 3]

def test_cli_emits_each_generator_result_as_a_line():
    result = run(".[]", ["a", "b", "c"])
    assert result.returncode == 0
    assert [json.loads(line) for line in result.stdout.splitlines()] == ["a", "b", "c"]

